  const { command, values } = parse(argv);
  const npm = values['--npm'] ?? 'npm';
  if (command === 'review') return reviewRuntimeTransfer({ runtimeDirectory: resolve(required(values, '--runtime')) });
  const directory = resolve(required(values, '--directory'));
