  const current = rows[0] ?? null;
  const adoption = release ? null : connection;
  const phase = !release ? 'CONNECTING' : !current ? 'READY' :
    current.active ? current.stop ? 'STOPPING' : current.url ? 'RUNNING' : 'STARTING' :
