  const homes = new Map();
  const items = await Promise.all(names.map(async id => {
    try { return await view(root, await application(root, id), { homes, historyLimit }); }
    catch (error) { return { id, label: id, phase: 'UNAVAILABLE', error: errorView(error) }; }
