/* Applications library and setup remain usable with long names and narrow windows. */
#application-library,#application-setup-drafts{min-width:0}
#application-library .runtime-list{display:flex}
#application-library .operation h3,#application-library .operation p,#application-library .actions .note{overflow-wrap:anywhere}
#applications-workspace .columns{grid-template-columns:repeat(2,minmax(0,1fr))}
#applications-workspace .columns>*{min-width:0}
@media(max-width:950px){#applications-workspace .columns{grid-template-columns:minmax(0,1fr)}}

#application-library .application-library-row{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:8px;align-items:start}
#application-library .application-library-row .runtime-entry{min-width:0}
#application-library .application-library-row>button[aria-pressed=true]{background:var(--soft);border-color:var(--ink)}


/* Complete setup receiving uses the workspace's existing industrial controls. */
.application-setup-library{margin-top:16px;border-top:1px solid var(--line);padding-top:12px}
.application-setup-library .application-setup-table{max-width:100%;overflow:auto}
.application-setup-library table{width:100%;min-width:680px;table-layout:fixed}
.application-setup-library th,.application-setup-library td{vertical-align:top;overflow-wrap:anywhere}
.application-setup-library td pre{margin:0;padding:0;background:transparent;white-space:pre-wrap;overflow-wrap:anywhere}
.application-setup-library td select{width:100%;min-width:0}
.application-setup-library .application-setup-comparison{margin:16px 0}

/* MIT. Application groups use the existing monochrome operator system. */
.application-groups { min-width: 0; }
.application-groups .group-choices { display: grid; gap: 8px; max-height: 330px; overflow: auto; border: 1px solid var(--line); padding: 12px; margin-bottom: 20px; }
.application-groups .group-choice { display: flex; justify-content: space-between; align-items: center; gap: 16px; }
.application-groups .group-choice strong, .application-groups .group-choice small,
.application-groups .group-order small { display: block; overflow-wrap: anywhere; }
.application-groups small { color: var(--muted); font-size: 11px; }
.application-groups .group-choice button { flex: 0 0 auto; }
.application-groups .group-order, .application-groups .group-run-members { padding-left: 24px; }
.application-groups .group-order > li, .application-groups .group-run-members > li { padding: 14px 0 14px 8px; border-bottom: 1px solid var(--line); }
.application-groups .group-order .actions { margin: 10px 0 0; }
.application-groups .group-review-member { padding: 18px 0; border-bottom: 1px solid var(--line); }
.application-groups pre { white-space: pre-wrap; overflow-wrap: anywhere; max-height: 440px; overflow: auto; }
.application-groups .paths dd { font-size: 11px; }
.application-groups .panel .message { padding: 12px; margin: 12px 0; overflow-wrap: anywhere; }
.application-groups details > div > button { display: block; text-align: left; margin: 8px 0; max-width: 100%; overflow-wrap: anywhere; }
.application-groups fieldset:disabled { opacity: .65; }
@media (max-width: 760px) {
  .application-groups .group-choice { align-items: flex-start; }
  .application-groups .paths div { grid-template-columns: 1fr; gap: 3px; }
  .application-groups .section-title { flex-wrap: wrap; gap: 8px; }
}

