/* MIT. Standalone and original Runtime product briefing. */
body:has(> .product-briefing) { margin: 0; background: #fff; }
.product-briefing { max-width: 1120px; margin: 0 auto; padding: 36px 28px 64px; background: #fff; color: #171717; font: 15px/1.5 system-ui, sans-serif; }
.product-briefing header { display: block; border-bottom: 2px solid #222; padding-bottom: 18px; margin-bottom: 28px; }
.product-briefing h1 { font-size: 30px; line-height: 1.2; margin: 6px 0 12px; overflow-wrap: anywhere; }
.product-briefing .eyebrow { font-size: 12px; letter-spacing: .08em; text-transform: uppercase; margin: 0; }
.product-briefing .meta { font-size: 13px; color: #555; margin: 0; }
.product-briefing h2 { font-size: 21px; margin: 28px 0 12px; }
.product-briefing h3 { font-size: 16px; margin: 20px 0 8px; }
.product-briefing p { white-space: pre-wrap; overflow-wrap: anywhere; margin: 8px 0 14px; }
.product-briefing .table { overflow: auto; margin: 12px 0 22px; }
.product-briefing table { border-collapse: collapse; width: 100%; font-size: 12px; table-layout: fixed; }
.product-briefing th, .product-briefing td { text-align: left; vertical-align: top; padding: 9px 10px; border: 1px solid #ccc; overflow-wrap: anywhere; }
.product-briefing th { background: #f2f2f2; font-weight: 600; }
.product-briefing thead { display: table-header-group; }
.product-briefing section { margin: 0 0 26px; }
.product-briefing details { border-top: 1px solid #ccc; padding-top: 10px; margin: 22px 0; }
.product-briefing summary { cursor: pointer; font-weight: 600; }
dialog[data-product-briefing] { width: min(1200px, calc(100vw - 32px)); max-width: 96vw; max-height: 94vh; padding: 0; border: 1px solid #999; background: #fff; color: #171717; }
dialog[data-product-briefing] .briefing-toolbar { position: sticky; top: 0; z-index: 1; display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 8px; padding: 12px 16px; border-bottom: 1px solid #ccc; background: #fff; }
dialog[data-product-briefing] .briefing-toolbar h3 { margin: 0; }
@media (max-width: 600px) {
  .product-briefing { padding: 22px 14px 40px; }
  .product-briefing h1 { font-size: 25px; }
  .product-briefing th, .product-briefing td { padding: 7px 6px; }
}
@page product-briefing { size: A4 landscape; margin: 15mm; }
@media print {
  body:has(> dialog[data-product-briefing][open]) > :not(dialog[data-product-briefing]) { display: none !important; }
  dialog[data-product-briefing][open] { display: block; position: static; inset: auto; width: auto; max-width: none; height: auto; max-height: none; overflow: visible; padding: 0; margin: 0; border: 0; box-shadow: none; }
  dialog[data-product-briefing] .briefing-toolbar { display: none; }
  dialog[data-product-briefing]::backdrop { display: none; }
  .product-briefing { page: product-briefing; max-width: none; padding: 0; font-size: 10pt; }
  .product-briefing h1 { font-size: 22pt; }
  .product-briefing h2 { font-size: 15pt; break-after: avoid; }
  .product-briefing h3 { break-after: avoid; }
  .product-briefing th, .product-briefing td { font-size: 8pt; padding: 5px 6px; }
  .product-briefing tr { break-inside: avoid; }
  .product-briefing .table { overflow: visible; }
  .product-briefing header { break-inside: avoid; }
  .product-briefing p { orphans: 3; widows: 3; }
  .product-briefing details:not([open]) { display: none; }
}

/* Committed product discovery uses the same neutral operator controls. */
.source-catalog-controls{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:16px;align-items:end}
.source-catalog-list{display:grid;gap:8px}
.source-catalog-row{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:12px;align-items:start}
.source-catalog-row .runtime-entry{margin:0;height:100%}
.source-catalog-row .check{margin:10px 0;white-space:nowrap}
.source-catalog-unavailable{min-width:0;padding:10px;border:1px solid var(--line);background:var(--soft)}
.source-catalog-unavailable strong,.source-catalog-unavailable p{overflow-wrap:anywhere}
.source-catalog-selection{border-top:1px solid var(--line);padding-top:16px;margin-top:18px;overflow-wrap:anywhere}
[data-product-preview] .facts{grid-template-columns:repeat(4,minmax(0,1fr))}
[data-comparison] td{white-space:pre-wrap}
[data-comparison] .table-wrap{max-height:420px}
@media(max-width:650px){
.source-catalog-controls{grid-template-columns:minmax(0,1fr);gap:0}
.source-catalog-row{grid-template-columns:minmax(0,1fr)}
.source-catalog-row .check{margin:0 0 12px}
[data-product-preview] .facts{grid-template-columns:repeat(2,minmax(0,1fr))}
}

